const THROTTLE_MS = 10 * 60 * 1000;
const items = $input.all();
const out = [];
const staticData = $getWorkflowStaticData('global');
if (!staticData.lastNotifyByWorkflow) staticData.lastNotifyByWorkflow = {};

for (const item of items) {
  const j = item.json || {};
  const workflow = j.workflow || {};
  const execution = j.execution || {};
  const err = execution.error || j.error || {};
  const wfId = String(workflow.id || 'unknown');
  const wfName = String(workflow.name || wfId);
  const execId = String(execution.id || '');
  const lastNode = String(execution.lastNodeExecuted || '');
  const msg = String(err.message || err.description || err || 'Unknown error').slice(0, 1200);
  const now = Date.now();
  const last = Number(staticData.lastNotifyByWorkflow[wfId] || 0);
  if (now - last < THROTTLE_MS) {
    continue; // throttle: max 1 notify / 10 min per workflow
  }
  staticData.lastNotifyByWorkflow[wfId] = now;

  const execUrl = execution.url
    || (execId ? `https://n8n.redbuttonedu.cz/workflow/${wfId}/executions/${execId}` : `https://n8n.redbuttonedu.cz/workflow/${wfId}`);
  const lines = [
    ':x: *n8n Error*',
    `*Workflow:* ${wfName}`,
    lastNode ? `*Node:* \`${lastNode}\`` : null,
    execId ? `*Execution:* \`${execId}\`` : null,
    msg ? `*Error:* ${msg}` : null,
    `<${execUrl}|Open in n8n>`,
  ].filter(Boolean);
  out.push({ json: { slackText: lines.join('\n'), workflowId: wfId, workflowName: wfName, executionId: execId } });
}
return out;
